}

// dsa_sparse_fwd_split_for: the forward's split recommendation -- the same
// CU-fill formula one level up (blocks = ceildiv(S_q, BQ)*H per split, so
// the CU term divides by the whole per-split grid, and the range term keeps
// >= 1 block_I tile per split). Decode shapes are the target: at S_q=1 the
// plain grid is H blocks, so split = min(ceildiv(topk, block_I), 228/H).
TEST(DsaSparse, SplitFor) {
  using vkernels::kernels::dsa_sparse_fwd_split_for;
  // GLM-5.3-Flash full-topk decode: 64 blocks -> min(32, 228/64=3) = 3.
  EXPECT_EQ(dsa_sparse_fwd_split_for(1, 64, 2048, 64, 228), 3);
  // topk=256 decode: range term 4 binds before the CU term (228/64 = 3 ->
  // min(4, 3) = 3).
  EXPECT_EQ(dsa_sparse_fwd_split_for(1, 64, 256, 64, 228), 3);
  // DeepSeek-V3 decode (H=16): 16 blocks -> min(4, 228/16=14) = 4.
  EXPECT_EQ(dsa_sparse_fwd_split_for(1, 16, 256, 64, 228), 4);
  // Huge H saturates the CUs with the plain grid: no split.
  EXPECT_EQ(dsa_sparse_fwd_split_for(1, 256, 2048, 64, 228), 1);
  // Prefill S_q=8192 (BQ=4): 2048*H blocks >> CUs -> split 1.
  EXPECT_EQ(dsa_sparse_fwd_split_for(8192, 1, 128, 64, 228), 1);
  // The range cap: topk=128, block_I=64 -> at most 2 splits.
  EXPECT_EQ(dsa_sparse_fwd_split_for(1, 8, 128, 64, 228), 2);
  // Tiny shape: topk=2 with block_I=2 -> at most 1 split.
  EXPECT_EQ(dsa_sparse_fwd_split_for(1, 1, 2, 2, 228), 1);
  // Degenerate inputs -> safe 1.
  EXPECT_EQ(dsa_sparse_fwd_split_for(0, 64, 2048, 64, 228), 1);
  EXPECT_EQ(dsa_sparse_fwd_split_for(1, 64, 0, 64, 228), 1);
  EXPECT_EQ(dsa_sparse_fwd_split_for(1, 64, 2048, 0, 228), 1);
  EXPECT_EQ(dsa_sparse_fwd_split_for(1, 64, 2048, 64, 0), 3);  // default CUs
}

