  if (S_q <= 0 || H <= 0 || topk <= 0 || block_I <= 0) return 1;
  int bq = 0, th = 0, bi = 0, ii = 0;
  dsa_config_for(S_q, H, /*dim=*/0, topk, &bq, &th, &bi, &ii);
  const int blocks = ((S_q + bq - 1) / bq) * H;   // blocks per single split
  const int by_range = (topk + block_I - 1) / block_I;  // >= 1 tile/split
  int s = num_cu / (blocks > 0 ? blocks : 1);     // floor, like the indexer
  s = s < by_range ? s : by_range;
  return s < 1 ? 1 : s;
}

